const fs=require('node:fs'),cp=require('node:child_process'),crypto=require('node:crypto');
const hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
function walk(base){if(!fs.existsSync(base))return null;const out={};function step(p){for(const d of fs.readdirSync(p,{withFileTypes:true})){const n=p+'/'+d.name;if(d.isDirectory())step(n);else if(d.isFile())out[n]=hash(n);else out[n]='other';}}step(base);return out;}
function run(args){const r=cp.spawnSync('git',['-C','/app',...args],{encoding:'utf8'});return {args,code:r.status,stdout:r.stdout,stderr:r.stderr};}
const out={appEntries:fs.readdirSync('/app'),gitTree:run(['ls-tree','-r','HEAD']),gitLog:run(['log','--all','--name-status','--oneline']),gitFsck:run(['fsck','--full','--no-reflogs']),inputs:{...walk('/instructions'),...walk('/assets')},otherRoots:{},privatePaths:{}};
